(()=>{if(location.pathname.startsWith('/cms'))return;
const fields=[['name','Nama Sesuai KTP','text'],['phone','No. HP','tel'],['nik','NIK Sesuai KTP','text'],['job','Pekerjaan','text'],['company','Nama Perusahaan / Kampus','text'],['address','Alamat Domisili','textarea'],['email','Email','email'],['social','Akun Media Sosial','text']],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let dialog,photos={selfie:[],ktp:[]},urls=[],text='';
function install(){const bottom=document.querySelector('.rc-app-nav');if(bottom&&!bottom.querySelector('[data-register-member]')){const button=document.createElement('button');button.type='button';button.dataset.registerMember='';button.setAttribute('aria-label','Daftar Member Baru');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M19 8v6M16 11h6"/></svg><span>Daftar</span>';bottom.insertBefore(button,bottom.querySelector('[href="/cart"]'));}const nav=document.querySelector('#drawer .rc-drawer-nav')||document.querySelector('#drawer');if(nav&&!nav.querySelector('[data-register-member]'))nav.insertAdjacentHTML('beforeend','<button class="drawer-link" type="button" data-register-member><span class="drawer-link-icon"><svg viewBox="0 0 24 24"><circle cx="9" cy="8" r="4"/><path d="M2 21v-2a7 7 0 0 1 14 0v2M19 8v6M16 11h6"/></svg></span><span><b>Daftar Member Baru</b><small>Registrasi langsung ke WhatsApp</small></span></button>')}
function target(){let n=String(window.RENTCAM_CMS_CONFIG?.general?.marketingWhatsapp||window.RENTCAM_CMS_CONFIG?.general?.whatsapp||'').replace(/\D/g,'');if(n.startsWith('0'))n='62'+n.slice(1);else if(n.startsWith('8'))n='62'+n;return n}
function message(f){return ['*FORM REGISTRASI MEMBER BARU*','',...fields.map(([key,label])=>label+': '+f.elements[key].value.trim()),'','*LAMPIRAN*','Foto selfie: '+photos.selfie.length+' foto','Foto KTP: '+photos.ktp.length+' foto','','Foto selfie dan KTP akan dilampirkan langsung di chat WhatsApp.'].join('\n')}
function preview(){urls.forEach(URL.revokeObjectURL);urls=[];for(const kind of ['selfie','ktp']){const host=dialog.querySelector('[data-member-photos='+kind+']');host.innerHTML=photos[kind].map((file,i)=>{const u=URL.createObjectURL(file);urls.push(u);return `<div><img src="${u}" alt="${kind==='ktp'?'KTP':'Selfie'} ${i+1}"><span>${esc(file.name)}</span><button type="button" data-member-remove="${kind}" data-index="${i}">Hapus</button></div>`}).join('')}update()}
function update(){const f=dialog.querySelector('form');const host=dialog.querySelector('[data-member-summary]');host.innerHTML='<h3>Rincian registrasi</h3><dl>'+fields.map(([k,l])=>'<div><dt>'+l+'</dt><dd>'+esc(f.elements[k].value.trim()||'Belum diisi')+'</dd></div>').join('')+'<div><dt>Foto selfie</dt><dd>'+photos.selfie.length+' foto</dd></div><div><dt>Foto KTP</dt><dd>'+photos.ktp.length+' foto</dd></div></dl>';text=message(f)}
function close(){urls.forEach(URL.revokeObjectURL);urls=[];photos={selfie:[],ktp:[]};text='';dialog?.remove();dialog=null}
function open(){if(dialog)return;document.getElementById('drawer')?.classList.remove('open');document.body.classList.remove('menu-open');dialog=document.createElement('dialog');dialog.id='rcMemberDialog';dialog.innerHTML=`<div class="rc-review-heading"><div><h2>Form Registrasi Member</h2><p>Kirim data langsung ke WhatsApp marketing.</p></div><button type="button" data-member-close aria-label="Tutup form">×</button></div><form autocomplete="off"><div class="rc-member-fields">${fields.map(([key,label,type])=>`<label>${label}${type==='textarea'?`<textarea name="${key}" required maxlength="1000" rows="3"></textarea>`:`<input name="${key}" type="${type}" required maxlength="${key==='nik'?16:200}" ${key==='nik'?'inputmode="numeric" pattern="[0-9]{16}" minlength="16" title="NIK harus 16 angka"':key==='phone'?'inputmode="tel" pattern="[+0-9 ()-]{8,20}"':key==='name'?'minlength="2"':''}>`}</label>`).join('')}</div>${['selfie','ktp'].map(kind=>`<section class="rc-member-upload"><h3>Upload foto ${kind==='selfie'?'selfie':'KTP'}</h3><p>Bisa tambah beberapa foto. Maksimal 10 foto per bagian, 10 MB per foto.</p><input type="file" data-member-upload="${kind}" accept="image/*" multiple aria-label="Tambah foto ${kind}"><div class="rc-member-photos" data-member-photos="${kind}"></div></section>`).join('')}<section data-member-summary></section><p class="rc-member-note">Data dan foto tidak disimpan ke database atau server. Form akan kosong saat ditutup atau halaman dimuat ulang.</p><p role="status" data-member-status></p><button type="submit" class="btn">Kirim Registrasi & Foto ke WhatsApp</button></form>`;document.body.append(dialog);dialog.addEventListener('close',close);dialog.querySelector('[data-member-close]').onclick=()=>dialog.close();dialog.querySelector('form').addEventListener('input',update);dialog.addEventListener('change',e=>{const kind=e.target.dataset.memberUpload;if(!kind)return;const list=[...e.target.files],status=dialog.querySelector('[data-member-status]');if(list.some(f=>f.size>10*1024*1024||!f.type.startsWith('image/'))||photos[kind].length+list.length>10){status.textContent='Pilih maksimal 10 foto per bagian, masing-masing sampai 10 MB.';e.target.value='';return}photos[kind].push(...list);e.target.value='';status.textContent='';preview()});dialog.addEventListener('click',async e=>{const del=e.target.closest('[data-member-remove]');if(del){photos[del.dataset.memberRemove].splice(Number(del.dataset.index),1);preview()}});dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const status=dialog.querySelector('[data-member-status]');if(!photos.selfie.length||!photos.ktp.length){status.textContent='Tambahkan minimal satu foto selfie dan satu foto KTP.';return}const phone=target();if(!/^62\d{7,14}$/.test(phone)){status.textContent='Nomor WhatsApp marketing belum diatur. Hubungi admin.';return}text=message(f);location.assign('https://wa.me/'+phone+'?text='+encodeURIComponent(text))};update();dialog.showModal()}
document.addEventListener('click',e=>{if(e.target.closest('[data-register-member]')){e.preventDefault();open()}},true);const drawer=document.getElementById('drawer');if(drawer)new MutationObserver(install).observe(drawer,{childList:true,subtree:true});new MutationObserver(install).observe(document.body,{childList:true,subtree:true});install();
})();
